// app.js — client bootstrap (ES module).
// Reads #app-config (JSON) generated by Jinja, imports feature modules, and
// initializes the current DOM. Safe if htmx replaces the editor or templates
// section multiple times: initializers are idempotent.
// The window bridge below exposes the function names required by legacy
// inline onclick handlers; it carries no mutable state.

import { jumpDate, requestNavigate, scrollDates, selectDate } from './date-navigation.js';
import {
    addRowAfter,
    eliminarSesion,
    fitRowsToPanel,
    initEditorRowSortable,
    removeRow,
    syncEditorFromContent,
    toggleEdit,
} from './editor.js';
import { initLifecycle } from './htmx-lifecycle.js';
import { scheduleNotices } from './notices.js';
import { setCategoriaMap } from './state.js';
import {
    aplicarPlantilla,
    confirmEntrenoSave,
    editarPlantilla,
    eliminarPlantilla,
    guardarPlantillaToggle,
    initEntrenoDnD,
    initTemplateSortable,
    ptAddRow,
    ptRemoveRow,
    refreshPlantillas,
} from './templates.js';

function loadConfig() {
    const el = document.getElementById('app-config');
    if (!el) return;
    try {
        const config = JSON.parse(el.textContent);
        setCategoriaMap(config.categoria_map || {});
    } catch (err) {
        console.error('app-config no válido', err);
    }
}

function registerInlineHandlers() {
    window.toggleEdit = toggleEdit;
    window.guardarPlantillaToggle = guardarPlantillaToggle;
    window.confirmEntrenoSave = confirmEntrenoSave;
    window.eliminarSesion = eliminarSesion;
    window.addRowAfter = addRowAfter;
    window.removeRow = removeRow;
    window.aplicarPlantilla = aplicarPlantilla;
    window.eliminarPlantilla = eliminarPlantilla;
    window.editarPlantilla = editarPlantilla;
    window.refreshPlantillas = refreshPlantillas;
    window.ptAddRow = ptAddRow;
    window.ptRemoveRow = ptRemoveRow;
    window.selectDate = selectDate;
    window.scrollDates = scrollDates;
    window.jumpDate = jumpDate;
    window.requestNavigate = requestNavigate;
}

document.addEventListener('DOMContentLoaded', function () {
    loadConfig();
    registerInlineHandlers();
    initLifecycle();
    scheduleNotices();
    syncEditorFromContent();
    initEditorRowSortable();
    initTemplateSortable();
    initEntrenoDnD();
    fitRowsToPanel();
});
